import {BELL_NOTES,BELL_CARDS,BELL_PAIRS,BELL_MODEL,BELL_REFLECTION,bellNoteById} from './bell-studio-content.mjs';
import {bellState,bellView,chooseBellCard,nextBellCard,setBellPage,appendBellSlot,selectBellSlot,replaceBellSlot,moveBellSlot,removeBellSlot,clearBellSequence,inspectBellSlot,saveBellBefore,chooseBellPair,setBellComparisonResponse,checkBellComparison,checkBellArrangement,useBellSupport,keepBellCall,recoverBellStudio,bellPlaybackPlan} from './bell-studio-core.mjs';
import {bellNoteArt,bellSignalArt,bellSequenceArt} from './bell-studio-art.mjs';
import {hearButton} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(attr,label,{on=null,disabled=false,primary=false}={})=>`<button type="button" class="${primary?'primary':'secondary'}${on?' selected':''}" ${attr}${on===null?'':` aria-pressed="${on}"`}${disabled?' disabled':''}>${label}</button>`;
const words=s=>s.length?s.map(id=>bellNoteById(id).name).join(', '):'Empty draft';
const pages=[['make','Make'],['compare','Compare'],['keep','Keep or revise']];
function heading(){return '<header class="bs-heading"><a class="back" href="#home">← Back to the garden</a><h1>The Bell Studio</h1><p>A little call for a gathering, a delivery, or an idea of your own.</p></header>';}
function chooser(r){return `<section class="bs-chooser"><h2 id="bs-title" tabindex="-1">Who shall we make a call for?</h2><div class="bs-card-grid">${BELL_CARDS.map(c=>button(`data-bs-card="${c.id}"`,`<strong>${esc(c.title)}</strong><span>${esc(c.purpose)}</span><small>${r.cards[c.id]?'Your familiar call is waiting':'An open invitation'}${r.cards[c.id]?.kept?' · kept draft':''}</small>`)).join('')}</div><p class="tiny">No sound plays until you press Play or Hear. Your café and delivery drafts will wait.</p></section>`;}
function request(v){return `<section class="bs-request"><strong>${esc(v.card.title)}</strong><p>${esc(v.card.purpose)}</p><p><b>Our invitation:</b> ${esc(v.card.request)}</p>${v.work.familiar?'<span class="tiny">A familiar invitation to revisit.</span>':''}</section>`;}
function playback(v){return `<div class="bs-playbar">${button('data-bs-play="current"','Play my call',{primary:true,disabled:!v.actions.play})}${button('data-bs-stop','Stop sound')}<span id="bs-play-status" role="status">Sound starts only when you ask.</span></div><p class="tiny">${esc(BELL_MODEL.volumeCue)}</p>`;}
function composer(v){return `<section class="bs-compose"><div class="bs-add-buttons" role="group" aria-label="Add a silent composition slot">${BELL_NOTES.map(n=>button(`data-bs-add="${n.id}"`,`${bellNoteArt(n.id)}<span>Add ${n.name}</span>`,{disabled:!v.actions.append})).join('')}</div>${!v.actions.append?'<p class="bs-limit">Eight slots are filled. Select one to change it, or remove a slot.</p>':''}<ol class="bs-slots" aria-label="Your complete call in order">${v.sequence.map((id,i)=>`<li>${button(`data-bs-slot="${i}"`,`<small>Slot ${i+1}</small>${bellNoteArt(id)}<span>${bellNoteById(id).name}</span>`,{on:v.selected===i})}</li>`).join('')||'<li class="bs-empty">Your call starts here. Add a tone or a rest.</li>'}</ol><p class="tiny">${esc(words(v.sequence))}. Each slot lasts the same short beat.</p>${v.selected!==null?`<section class="bs-edit"><h3>Change slot ${v.selected+1}</h3><div class="bs-controls">${BELL_NOTES.map(n=>button(`data-bs-replace="${n.id}"`,n.name,{on:v.sequence[v.selected]===n.id})).join('')}</div><div class="bs-controls">${button('data-bs-move="-1"','Move left',{disabled:!v.actions.moveLeft})}${button('data-bs-move="1"','Move right',{disabled:!v.actions.moveRight})}${button('data-bs-remove','Remove this slot')}</div></section>`:''}<div class="bs-controls">${button('data-bs-clear','Clear working call',{disabled:!v.sequence.length})}${button('data-bs-before',v.before?'Replace my before-version':'Save this version to compare')}${button('data-bs-check','Check this arrangement')}</div>${arrangementFeedback(v)}<div class="bs-inspect" tabindex="-1"><h3>Explore the pictures without sound</h3><div class="bs-controls">${button('data-bs-inspect="-1"','Inspect previous slot',{disabled:!v.actions.inspect})}${button('data-bs-inspect="1"','Inspect next slot',{disabled:!v.actions.inspect})}</div>${v.inspected?`<p role="status">Slot ${v.inspected.index+1}: <strong>${bellNoteById(v.inspected.id).name}</strong>. ${v.inspected.id==='rest'?'A silent beat.':'A sounding note in the picture call.'}</p>`:''}</div></section>`;}
function arrangementFeedback(v){const s=v.work.feedback.arrangement?v.latestArrangement:null;return s?`<section id="bs-feedback" class="bs-feedback" tabindex="-1" role="status"><p>${esc(v.arrangementFeedback)}</p><ul>${s.assessment.items.map(x=>`<li>${x.match?'Matches':'Still different'}: ${esc(x.label)}.</li>`).join('')}</ul></section>`:v.priorArrangement?`<details class="bs-prior"><summary>An earlier arrangement check is kept</summary><p>It checked: ${esc(words(v.priorArrangement.sequence))}. Your current call has changed or is waiting for another check.</p></details>`:'<div id="bs-feedback" tabindex="-1" hidden></div>';}
function comparison(v){return `<section class="bs-versions"><div><h3>My before-version</h3>${v.before?`${bellSequenceArt(v.before.sequence,{label:'Frozen before-version'})}${button('data-bs-play="before"','Play before',{disabled:!v.before.sequence.length})}`:'<p>Save a version on Make, then change your call. Your first version will stay here.</p>'}</div><div><h3>My current version</h3>${bellSequenceArt(v.sequence,{label:'Current version'})}${button('data-bs-play="current"','Play current',{disabled:!v.sequence.length})}</div></section>${v.changes?`<p>${v.changes.positions.length?`Changed slots: ${v.changes.positions.map(p=>p.position).join(', ')}.`:'The two pictured versions are the same.'}</p>`:''}<p>${esc(BELL_REFLECTION)}</p><section class="bs-pair"><h3>A little pitch comparison</h3><div class="bs-controls" role="group" aria-label="Choose a finite computer-tone pair">${BELL_PAIRS.map(p=>button(`data-bs-pair="${p.id}"`,p.title,{on:v.pair.id===p.id})).join('')}</div><p>Source pair: ${esc(words(v.pair.sequence))}.</p>${button('data-bs-play="pair"','Play this pair')}${v.work.support.ladder?bellSequenceArt(v.pair.sequence,{label:'Supplied pair with Low, Middle and High pitch labels'}):''}<p>In this computer pair, how is the second tone set?</p><div class="bs-controls" role="group" aria-label="A comparison draft">${[['higher','Higher'],['lower','Lower'],['same','The same'],['not-sure','Not sure']].map(([id,label])=>button(`data-bs-response="${id}"`,label,{on:v.response===id})).join('')}</div>${button('data-bs-check-pair','Compare with the source',{disabled:!v.actions.checkComparison})}${v.comparisonFeedback?`<div class="bs-feedback" id="bs-pair-feedback" role="status" tabindex="-1">${esc(v.comparisonFeedback)}</div>`:'<div id="bs-pair-feedback" hidden tabindex="-1"></div>'}<p class="tiny">Listen, use the pictures, or explore together. This is practice with a supplied model, not a hearing test.</p></section>`;}
function keep(v){const k=v.work.kept;return `<p>A call can hold an unfinished idea. Keep it as it is, or try another version.</p>${bellSequenceArt(v.sequence)}${button('data-bs-keep',k?'Replace this invitation’s kept draft':'Keep this call draft',{primary:true})}<p>${button('data-bs-page="make"','Change my call')}</p>${k?`<section class="bs-kept" id="bs-kept" tabindex="-1"><h3>Your kept call draft</h3>${bellSequenceArt(k.sequence,{label:'Kept call draft'})}<p>This call is kept as a draft. A listener can help decide what the call means.</p><details><summary>What travels with this draft?</summary><p>${esc(k.source.purpose)}</p><p>Visible-source practice${k.familiar?', familiar':''}. Support: ${esc(Object.keys(k.support).join(', '))}.</p><p>Your before-version and earlier checks stay with the snapshot. Later edits do not change it.</p></details></section>`:''}<p>${esc(BELL_REFLECTION)}</p>`;}
function support(v){const s=v.work.support;return `<aside class="bs-support" tabindex="-1"><div class="bs-controls">${button('data-bs-support="ladder"','Show the pitch ladder',{on:!!s.ladder})}${button('data-bs-support="signalDiagram"','Explore the source signal',{on:!!s.signalDiagram})}${button('data-bs-support="together"',s.together?'Working together is kept':'We’re working together',{on:!!s.together})}<span data-bs-audio>${hearButton(`${v.card.purpose} ${v.card.request} ${BELL_MODEL.notice} All pages stay open; you can keep an unfinished call.`,'Hear this invitation')}</span></div>${s.ladder?`<section class="bs-ladder"><h3>Three relative pitches</h3><div>${BELL_NOTES.filter(n=>n.frequency!==null).map(n=>`<span>${bellNoteArt(n.id)}<strong>${n.name}</strong><small>${n.frequency} Hz</small></span>`).join('')}</div><p>Low, Middle and High name this set. Higher pitch does not mean louder.</p></section>`:''}${s.signalDiagram?bellSignalArt():''}<details><summary>About these computer sounds</summary><p>${esc(BELL_MODEL.notice)} ${esc(BELL_MODEL.idea)}</p><p>The source signal uses the same digital gain setting for each note. Devices and people can respond differently; equal gain does not promise equal perceived loudness. The pictures do not show measured speaker movement or a real bell.</p></details></aside>`;}
export function bellStudioEntry(){return '<aside class="bs-entry"><div><h2>A call for the neighborhood</h2><p>Make a little computer-tone call, try it, then change it for a listener.</p></div><a class="secondary" href="#studio/bells">Open the Bell Studio</a></aside>';}
export function bellStudioPage(state){const r=bellState(state);if(!r)return '<section class="bs-workspace" data-bs-root><h1 id="bs-title" tabindex="-1">An earlier Bell Studio draft is kept</h1><p>This format cannot be opened here. The exact original stays in notes downloads.</p><button type="button" class="secondary" data-bs-recover>Keep the earlier record and continue</button><p><a href="#home">Return to the garden</a></p></section>';if(r.page==='choose'||!r.currentCard)return `<div class="bs-workspace" data-bs-root>${heading()}${chooser(r)}</div>`;const v=bellView(state);return `<div class="bs-workspace bs-page-${r.page}" data-bs-root>${heading()}${request(v)}<nav class="bs-pages" aria-label="Bell Studio turn">${pages.map(([id,label],i)=>button(`data-bs-page="${id}"`,`${i+1}. ${label}`,{on:r.page===id})).join('')}</nav><section class="bs-turn"><h2 id="bs-title" tabindex="-1">${r.page==='make'?'Make a call, one slot at a time':r.page==='compare'?'What changed for the listener?':'A call to keep or revise'}</h2>${playback(v)}${r.page==='make'?composer(v):r.page==='compare'?comparison(v):keep(v)}</section><section class="bs-previews" aria-label="Explicit single-tone previews"><p>Try one computer tone:</p><div class="bs-controls">${BELL_NOTES.filter(n=>n.frequency!==null).map(n=>button(`data-bs-hear="${n.id}"`,`Hear ${n.name}`)).join('')}</div></section>${support(v)}<div class="bs-footer">${button('data-bs-page="choose"','Choose another invitation')}${button('data-bs-next','Another invitation')}<a href="#cafe">Café</a><a href="#post">Post Office</a><a href="#notes">Grown-up notes</a></div></div>`;}
export function bindBellStudio(state,ctx){if(!document.querySelector('[data-bs-root]'))return;const player=ctx.player;const focus=selector=>{const e=document.querySelector(selector);ctx.focus?.(e&&!e.disabled?selector:'#bs-title');};const refresh=(target='#bs-title')=>{ctx.save();ctx.render();focus(target);};const act=(fn,target='#bs-title')=>{player?.stop('edit-or-page');if(fn()!==false)refresh(typeof target==='function'?target():target);};const all=(selector,fn)=>document.querySelectorAll(selector).forEach(el=>el.addEventListener('click',()=>fn(el)));all('[data-bs-card]',b=>act(()=>chooseBellCard(state,b.dataset.bsCard)));all('[data-bs-page]',b=>act(()=>setBellPage(state,b.dataset.bsPage)));all('[data-bs-next]',()=>act(()=>nextBellCard(state)));all('[data-bs-recover]',()=>act(()=>recoverBellStudio(state)));all('[data-bs-add]',b=>act(()=>appendBellSlot(state,b.dataset.bsAdd),`[data-bs-add="${b.dataset.bsAdd}"]`));all('[data-bs-slot]',b=>act(()=>selectBellSlot(state,Number(b.dataset.bsSlot)),`[data-bs-slot="${b.dataset.bsSlot}"]`));all('[data-bs-replace]',b=>{if(bellView(state).sequence[bellView(state).selected]===b.dataset.bsReplace)return;act(()=>replaceBellSlot(state,b.dataset.bsReplace),`[data-bs-replace="${b.dataset.bsReplace}"]`);});all('[data-bs-move]',b=>act(()=>moveBellSlot(state,Number(b.dataset.bsMove)),()=>`[data-bs-slot="${bellView(state).selected}"]`));all('[data-bs-remove]',()=>act(()=>removeBellSlot(state),()=>bellView(state).selected===null?'[data-bs-add="low"]':`[data-bs-slot="${bellView(state).selected}"]`));all('[data-bs-clear]',()=>act(()=>clearBellSequence(state),'[data-bs-add="low"]'));all('[data-bs-before]',()=>act(()=>saveBellBefore(state)));all('[data-bs-check]',()=>act(()=>checkBellArrangement(state),'#bs-feedback'));all('[data-bs-inspect]',b=>act(()=>inspectBellSlot(state,Number(b.dataset.bsInspect)),'.bs-inspect'));all('[data-bs-pair]',b=>{if(bellView(state).pair.id===b.dataset.bsPair)return;act(()=>chooseBellPair(state,b.dataset.bsPair));});all('[data-bs-response]',b=>act(()=>setBellComparisonResponse(state,b.dataset.bsResponse),`[data-bs-response="${b.dataset.bsResponse}"]`));all('[data-bs-check-pair]',()=>act(()=>checkBellComparison(state),'#bs-pair-feedback'));all('[data-bs-keep]',()=>act(()=>keepBellCall(state),'#bs-kept'));all('[data-bs-support]',b=>act(()=>useBellSupport(state,b.dataset.bsSupport),'.bs-support'));const highlight=i=>{document.querySelectorAll('[data-bs-slot]').forEach(b=>b.classList.toggle('bs-playing',Number(b.dataset.bsSlot)===i));};const report=value=>{const e=document.querySelector('#bs-play-status');if(e)e.textContent=value.message;if(['completed','stopped','unavailable','invalid','empty'].includes(value.status))highlight(-1);};const play=async (sequence,followCurrent=false,kind='call')=>{ctx.stopSpeech?.();if(bellPlaybackPlan(sequence)?.hasSound){useBellSupport(state,'audioRequested');if(kind==='pair')useBellSupport(state,'pairAudioRequested');}ctx.save();if(!player){report({status:'unavailable',message:'Sound is unavailable here. You can still build and compare the picture call.'});return;}try{await player.play(sequence,{onStatus:report,onStep:followCurrent?highlight:()=>highlight(-1),onEnd:()=>highlight(-1)});}catch{player.stop('playback-error');report({status:'unavailable',message:'Sound is unavailable here. You can still build and compare the picture call.'});}};all('[data-bs-play]',b=>{const v=bellView(state),kind=b.dataset.bsPlay;void play(kind==='before'?v.before?.sequence||[]:kind==='pair'?v.pair.sequence:v.sequence,kind==='current',kind);});all('[data-bs-hear]',b=>{void play([b.dataset.bsHear]);});all('[data-bs-stop]',()=>{player?.stop('manual-stop');report({status:'stopped',message:'Sound stopped. Your call is still here.'});});document.querySelectorAll('[data-bs-audio] [data-speak]').forEach(b=>b.addEventListener('click',()=>{player?.stop('speech');useBellSupport(state,'narration');ctx.save();}));}
export function bellStudioNotes(state){if(!Object.hasOwn(state,'bellStudio'))return '';return `<details class="panel" data-bs-notes><summary>Bell Studio: calls, versions and comparisons</summary><p>Original computer-tone compositions and visible-source practice. Literal request matches, a model pitch relation and artistic suitability are separate. Audio requests do not establish hearing, attention or perception. Before/kept versions and older checks retain their exact source and support.</p><pre>${esc(JSON.stringify(state.bellStudio,null,2))}</pre></details>`;}
